[class*="scheduled-releases-type"] td:not(.bea-highlight) {
                border: none !important;
            }
  #release-schedule-table {
    xvisibility: hidden;
  }
 [class*="scheduled-releases-type"] td .release-date span{
  color: #3c763d;

  display:block;
  font-size: 90%;
  /*border-bottom: solid 1px #3c763d;*/
}

.row-disabled {
  opacity: 0.5;
  /*text-decoration: line-through;*/
}
 .scheduled-date.bea-highlight{
  border-color: rgba(60,118,61,0.35);
  border-style: solid;
  border-radius: 0px 15px 15px 0px;
  border-width: 0px 3px 0px 0px;
 }

.ecl-banner:not(.ecl-banner--plain-background) {
  container-type: inline-size;
  background: #fff;
}

.ecl-banner .ecl-link__label, .ecl-banner .ecl-link__label > div {
  display: inline;
}

.text-shadow-none {
  text-shadow: none !important;
}

.estat-banner-background-image {
  width: 100%;
  min-height: 10rem;
  position: relative;
}
.ecl-banner--plain-background .estat-banner-background-image {
  display: none;
}

.estat-banner-img {
  top: 1rem;
  left: 25%;
  width: 50%;
  height: calc(100% - 2rem);
  z-index: 2;
  position: absolute;
  background-repeat: no-repeat;
  background-position: center center;
  background-size: contain !important;
}
.ecl-banner__credit {
  display: none;
}
.ecl-banner:hover .ecl-banner__credit {
  display: block;
}

.estat-banner-background-image.Left {
  background-position: left;
}
.estat-banner-background-image.Center {
  background-position: center;
}
.estat-banner-background-image.Right {
  background-position: right;
}

@media only screen and (min-width: 996px) {
  /* html:not(#__):not(#___) ... .page-editor__editable is liferay's selector when editing page */
	.ecl-banner--s, .ecl-banner--s .estat-banner-background-image, html:not(#__):not(#___) .ecl-banner--s .page-editor__editable.estat-banner-background-image {
    min-height: 15rem;
  }
  .ecl-banner--m, .ecl-banner--m .estat-banner-background-image, html:not(#__):not(#___) .ecl-banner--m .page-editor__editable.estat-banner-background-image {
    min-height: 20rem;
  }
  .ecl-banner--l, .ecl-banner--l .estat-banner-background-image, html:not(#__):not(#___) .ecl-banner--l .page-editor__editable.estat-banner-background-image {
    min-height: 30rem;
  }

  .estat-banner-img {
    top: 2.5rem;
    left: 46.5rem;
    height: calc(100% - 5rem);
    width: calc(100% - 47.5rem);
  }

  @container (max-width: 600px) {
    .ecl-banner.estat-half-width.ecl-banner--s .estat-banner-background-image {
      min-height: 30rem;
    }
    .ecl-banner.estat-half-width.ecl-banner--m .estat-banner-background-image {
      min-height: 35rem;
    }
    .ecl-banner.estat-half-width.ecl-banner--l .estat-banner-background-image {
      min-height: 40rem;
    }

    .ecl-banner.estat-half-width .estat-banner-img {
      left: 20%;
      width: 60%;
      height: calc(50% - 2rem);
    }
    .ecl-banner.estat-half-width .ecl-container {
      height: 50%;
      top: 50%;
    }

    .ecl-banner.estat-half-width .ecl-banner__container {
      padding-top: 0;
    }
  }
}

