.estat-homepage-banner {
	background: linear-gradient(90deg, #0A328E 15%, #00E9FF 85%, #082B7A 100%);
}
.estat-homepage-banner > div:first-child {
  width: 100%;
	height: 100%;
  position: absolute;
}

.estat-homepage-banner .ecl-banner__title, .estat-homepage-banner .ecl-banner__description-text {
  text-shadow: 0 0 4px #000;
}
.estat-homepage-banner .ecl-banner__title-text {
	font: var(--f-6xl);
}
.estat-homepage-banner .ecl-banner__description-text {
	font: var(--f-p-l);
	color: #fff;
}

.estat-homepage-banner .ecl-link--cta, .estat-banner .ecl-link--cta:active, .estat-banner .ecl-link--cta:hover {
	background-color: #fff;
}

.estat-homepage-banner .ecl-link__label > div {
  display: inline;
}

/* #main-content is needed to override global style from theme */
#main-content .estat-homepage-banner .ecl-link--cta:hover {
  text-decoration: underline;
  text-decoration-color: var(--ecl-color-primary);
}

@media (max-width: 995px) {
  .estat-homepage-banner {
    background: linear-gradient(180deg, #0A328E 35%, #00E9FF);
  }
  .estat-homepage-banner .ecl-banner__container {
    flex-direction: column;
  }

  .estat-homepage-banner > div:first-child  {
    border-bottom: 0 solid #fc0;
    height: 65%;
    left: 12%;
    position: absolute;
    bottom: 0;
  }
}

@media (min-width: 996px) {
  .estat-homepage-banner {
    max-height: 175px;
  }
  .estat-homepage-banner::before {
    padding-top: 15%;
  }

  .estat-homepage-banner .ecl-banner__container::before {
    height: calc(100% + 30px);
    right: 0;
    top: 0;
  }
}

