        position: relative;
        letter-spacing: 0.1rem;
    }
    .filter-list-title:after {
        content: '';
        display: block;
        border-bottom: 1px solid rgba(255, 255, 255, 0.4);
        position: absolute;
        bottom: 0;
        height: 0;
        line-height: 0;
        left: 10px;
        right: 10px;
    }
    .filter-list-title-text {
        flex-grow: 1;
        padding-right: 10px;
