    div.filter-list:last-child {
        border-bottom: 1px solid #dcdcdc;
    }

    .filter-list .stat-filter-list-cont .filter-list-cont-item {
        color: rgba(40, 107, 198, 1);
        display: flex;
        padding: 1.4rem;
        line-height: 1.2;
        position: relative;
    }
    .filter-list .stat-filter-list-cont .stat-facet-show {
        line-height: 1.2;
        padding: 1.4rem;
        text-align: right;
        cursor: pointer;
        display: none;
    }
    .filter-list .stat-filter-list-cont .stat-facet-show.__active {
        display: block;
